package com.example;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service
public class Orders {
  private final Gateway gateway;
  public Orders(Gateway gateway) { this.gateway = gateway; }
  @Transactional
  public void submit() { gateway.send(); }
}
interface Gateway { void send(); }

